import{_ as a,c as t,o as r,a5 as o}from"./chunks/framework.DYgWcJ6Z.js";const u=JSON.parse('{"title":"Setup","description":"","frontmatter":{},"headers":[],"relativePath":"manual/quick-start/setup.md","filePath":"manual/quick-start/setup.md","lastUpdated":1754235051000}'),i={name:"manual/quick-start/setup.md"};function l(n,e,s,d,p,h){return r(),t("div",null,e[0]||(e[0]=[o('<h1 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h1><p>To get started with JSAR, you need to get the followings ready:</p><ul><li>Install the <em>Play WebXR</em> app on your supported device: <a href="https://arstudio.rokid.com/" target="_blank" rel="noreferrer">Rokid AR Studio</a> or <a href="https://arlite.rokid.com/" target="_blank" rel="noreferrer">Rokid AR Lite</a>.</li><li>Create a common Web project, in simplest, just create a <code>index.html</code> file with some HTML content.</li></ul><h2 id="install-play-webxr" tabindex="-1">Install <em>Play WebXR</em> <a class="header-anchor" href="#install-play-webxr" aria-label="Permalink to &quot;Install _Play WebXR_&quot;">​</a></h2><p><em>Play WebXR</em> is an <a href="https://unity.com/" target="_blank" rel="noreferrer">Unity</a> application that can run on <a href="https://arstudio.rokid.com/" target="_blank" rel="noreferrer">Rokid AR Studio</a> and <a href="https://arlite.rokid.com/" target="_blank" rel="noreferrer">Rokid AR Lite</a>. You can install the latest application via the app store.</p><p>When you have an installed <em>Play WebXR</em> in your device and open it, then you will be guided to a standalone space created by <em>Play WebXR</em>, and like every Web browser does, there is an input box for you to input the URL you want to run.</p><h2 id="url-types-supported" tabindex="-1">URL types supported <a class="header-anchor" href="#url-types-supported" aria-label="Permalink to &quot;URL types supported&quot;">​</a></h2><p>Just like a Web browser can open an image, a video, etc., JSAR can open kinds of URLs, including.</p><h3 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h3><p>When a URL ends with <code>.jpg</code>, <code>.jpeg</code>, <code>.png</code>, it will be treated as an image and displayed on a virtual screen in the space.</p><h3 id="_3d-models" tabindex="-1">3D Models <a class="header-anchor" href="#_3d-models" aria-label="Permalink to &quot;3D Models&quot;">​</a></h3><p>Currently only <code>.glb</code> and <code>.gltf</code> files are supported as 3D models, when user type this kind of URL, a 3D model will be rendered in the space with a scaled size.</p><h3 id="html" tabindex="-1">HTML <a class="header-anchor" href="#html" aria-label="Permalink to &quot;HTML&quot;">​</a></h3><p>When a URL ends with <code>.html</code>, it will be treated as a <a href="https://en.wikipedia.org/wiki/HTML" target="_blank" rel="noreferrer">HTML</a> file and run in the space.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>In next section, we will start from <a href="./write-html.mdx.html">writing a sample HTML file</a>.</p>',16)]))}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
